<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">DataStream.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">ofFile</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(</span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECE6A;">saves/slot1.bin</span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">)            </span><span style="--shiki-light:#66707B;--shiki-light-font-style:inherit;--shiki-dark:#51597D;--shiki-dark-font-style:italic;">-- a path, written as it arrives</span></span>
